 d,ids,idx,*_=design();b,w,center,between=decomposition(d.fta.to_numpy(),d.games_played.to_numpy(),idx)
 frame=pd.DataFrame(dict(player_id=d.player_id,season=d.season,FTA=d.fta,GP=d.games_played,centered_between=b,within=w));frame.to_csv(E/'opportunity_decomposition.csv',index=False)
 save('opportunity_decomposition.json',dict(frozen_at=now(),formula='x=log1p(FTA/GP); between=mean(x) within player over all accounting seasons; within=x-between; centered_between=between-mean(between across unique players)',GP_handling='Require GP>0; no imputation',zero_FTA='Retain; rate=0 and log1p(rate)=0',player_averaging='Equal observed-season weights within each player, including zero-FTA seasons; equal unique-player weights for global between center',centering_constant=center,rows=len(d),players=len(ids),zero_rows=int((d.fta==0).sum()),max_absolute_player_mean_within=float(np.max(np.abs(np.bincount(idx,weights=w)/np.bincount(idx)))),csv_sha256=sha(E/'opportunity_decomposition.csv'),panel_sha256=sha(PANEL)))
