 save('model_protocol.json',model);save('freeze_receipt.json',dict(frozen_at=model['frozen_at'],stage3f_frozen_at=model['frozen_at'],model_protocol_sha256=sha(E/'model_protocol.json'),prior_protocol_sha256=sha(E/'prior_protocol.json')))
